SQL = "-- Rehearsal candidate only. Legacy records remain the application's source of truth.\n-- The application gets SELECT only until transactional synchronization is implemented.\nCREATE TABLE public.proc_suppliers (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK (source_revision >= 1),\n    name text NOT NULL CHECK (length(name) > 0),\n    category text,\n    approved boolean NOT NULL,\n    simulated boolean NOT NULL,\n    PRIMARY KEY (tenant, id)\n);\nCREATE TABLE public.proc_rfqs (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK (source_revision >= 1),\n    title text NOT NULL CHECK (length(title) > 0),\n    due_date date NOT NULL,\n    status text NOT NULL CHECK (length(status) > 0),\n    owner_id varchar(64) NOT NULL,\n    reviewer_id varchar(64),\n    PRIMARY KEY (tenant, id)\n);\nCREATE TABLE public.proc_rfq_lines (\n    tenant varchar(64) NOT NULL,\n    rfq_id varchar(64) NOT NULL,\n    line_index integer NOT NULL CHECK (line_index >= 0),\n    sku varchar(80) NOT NULL CHECK (length(sku) > 0),\n    quantity integer NOT NULL CHECK (quantity > 0),\n    unit text NOT NULL CHECK (unit = 'piece'),\n    specs jsonb NOT NULL CHECK (jsonb_typeof(specs) = 'object' AND specs <> '{}'::jsonb),\n    evidence_id varchar(64),\n    PRIMARY KEY (tenant, rfq_id, line_index),\n    UNIQUE (tenant, rfq_id, sku),\n    FOREIGN KEY (tenant, rfq_id) REFERENCES public.proc_rfqs (tenant, id)\n);\nCREATE TABLE public.proc_rfq_invitations (\n    tenant varchar(64) NOT NULL,\n    rfq_id varchar(64) NOT NULL,\n    supplier_id varchar(64) NOT NULL,\n    PRIMARY KEY (tenant, rfq_id, supplier_id),\n    FOREIGN KEY (tenant, rfq_id) REFERENCES public.proc_rfqs (tenant, id),\n    FOREIGN KEY (tenant, supplier_id) REFERENCES public.proc_suppliers (tenant, id)\n);\nCREATE INDEX ix_proc_rfqs_status_due ON public.proc_rfqs (tenant, status, due_date);\nCREATE INDEX ix_proc_lines_sku ON public.proc_rfq_lines (tenant, sku);\nCREATE INDEX ix_proc_invitations_supplier ON public.proc_rfq_invitations (tenant, supplier_id);\n\nINSERT INTO public.proc_suppliers\nSELECT tenant, id, revision, data->>'name', data->>'category',\n       (data->>'approved')::boolean, (data->>'simulated')::boolean\nFROM public.records WHERE kind = 'supplier';\nINSERT INTO public.proc_rfqs\nSELECT tenant, id, revision, data->>'title', (data->>'due_date')::date,\n       data->>'status', data->>'owner', data->>'reviewer'\nFROM public.records WHERE kind = 'rfq';\nINSERT INTO public.proc_rfq_lines\nSELECT r.tenant, r.id, (line.ordinality - 1)::integer, line.value->>'sku',\n       (line.value->>'quantity')::integer, line.value->>'unit',\n       line.value->'specs', line.value->>'evidence_id'\nFROM public.records r\nCROSS JOIN LATERAL jsonb_array_elements(r.data::jsonb->'lines')\n    WITH ORDINALITY AS line(value, ordinality)\nWHERE r.kind = 'rfq';\nINSERT INTO public.proc_rfq_invitations\nSELECT r.tenant, r.id, invitation.value\nFROM public.records r\nCROSS JOIN LATERAL jsonb_array_elements_text(r.data::jsonb->'invited') AS invitation(value)\nWHERE r.kind = 'rfq';\n\nDO $$\nDECLARE t text;\nBEGIN\n    FOREACH t IN ARRAY ARRAY['proc_suppliers','proc_rfqs','proc_rfq_lines','proc_rfq_invitations']\n    LOOP\n        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);\n        EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', t);\n        EXECUTE format('CREATE POLICY tenant_scope ON public.%I TO supplypilot_app USING (tenant = NULLIF(current_setting(''supplypilot.tenant'', true), '''')) WITH CHECK (tenant = NULLIF(current_setting(''supplypilot.tenant'', true), ''''))', t);\n        EXECUTE format('CREATE POLICY migration_owner ON public.%I TO supplypilot_migrator USING (true) WITH CHECK (true)', t);\n        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, supplypilot_app', t);\n        EXECUTE format('GRANT SELECT ON TABLE public.%I TO supplypilot_app', t);\n    END LOOP;\nEND $$;\n"


